cards.solution:
function ubah(x: number): string;
function ubah(x: string): number;
function ubah(x: number | string): number | string {
  if (typeof x === "number") return "Rp" + x;
  return x.length;
}
console.log(ubah(5000));
console.log(ubah("kopi") + 1);
